"use client"

import * as React from "react"
import { PlusIcon, XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"

type Field = { id: string; label: string }
type Operator = { id: string; label: string }
type Rule = { key: number; field: string; operator: string; value: string }

function Choice({ label, items, value, onChange }: { label: string; items: { id: string; label: string }[]; value: string; onChange: (v: string) => void }) {
  return (
    <Select aria-label={label} value={value} onChange={(k) => k !== null && onChange(String(k))}>
      <SelectTrigger className="w-full sm:w-40">
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {items.map((i) => (
          <SelectItem key={i.id} id={i.id}>
            {i.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

/**
 * Filter builder composed from aria-nova Select, Input (text-field) and
 * Button, after the diceui faceted filter: rules of field / operator / value
 * joined by one group conjunction.
 */
export default function FilterBuilder({
  heading = "Filters",
  fields = [
    { id: "status", label: "Status" },
    { id: "owner", label: "Owner" },
    { id: "updated", label: "Updated" },
  ],
  operators = [
    { id: "is", label: "is" },
    { id: "is-not", label: "is not" },
    { id: "contains", label: "contains" },
  ],
  onChange,
}: {
  heading?: string
  fields?: Field[]
  operators?: Operator[]
  onChange?: (filter: { match: "all" | "any"; rules: Omit<Rule, "key">[] }) => void
}) {
  const next = React.useRef(1)
  const [match, setMatch] = React.useState<"all" | "any">("all")
  const [rules, setRules] = React.useState<Rule[]>([{ key: 0, field: fields[0]?.id ?? "", operator: operators[0]?.id ?? "", value: "" }])
  React.useEffect(() => onChange?.({ match, rules: rules.map(({ key: _k, ...r }) => r) }), [match, rules, onChange])
  const update = (key: number, patch: Partial<Rule>) => setRules((rs) => rs.map((r) => (r.key === key ? { ...r, ...patch } : r)))

  return (
    <section data-slot="filter-builder" className="py-8">
      <div className="mx-auto max-w-5xl space-y-4 px-6">
        <div className="flex flex-wrap items-center gap-2 text-sm">
          <h2 className="font-heading text-lg font-semibold">{heading}</h2>
          <span className="text-muted-foreground">Match</span>
          <Choice
            label="Match"
            items={[{ id: "all", label: "all rules" }, { id: "any", label: "any rule" }]}
            value={match}
            onChange={(v) => setMatch(v as "all" | "any")}
          />
        </div>
        <ul className="space-y-2">
          {rules.map((r) => (
            <li key={r.key} className="flex flex-col gap-2 sm:flex-row sm:items-center">
              <Choice label="Field" items={fields} value={r.field} onChange={(v) => update(r.key, { field: v })} />
              <Choice label="Operator" items={operators} value={r.operator} onChange={(v) => update(r.key, { operator: v })} />
              <Input aria-label="Value" placeholder="Value" value={r.value} onChange={(e) => update(r.key, { value: e.target.value })} className="sm:flex-1" />
              <Button variant="ghost" size="icon" aria-label="Remove rule" isDisabled={rules.length === 1} onPress={() => setRules((rs) => rs.filter((x) => x.key !== r.key))}>
                <XIcon />
              </Button>
            </li>
          ))}
        </ul>
        <Button
          variant="outline"
          size="sm"
          onPress={() => setRules((rs) => [...rs, { key: next.current++, field: fields[0]?.id ?? "", operator: operators[0]?.id ?? "", value: "" }])}
        >
          <PlusIcon data-icon="inline-start" />
          Add rule
        </Button>
      </div>
    </section>
  )
}
